// EAN-13 helpers. Internal barcodes generated by the app start with 200 (reserved for in-store use).
export const INTERNAL_PREFIX = '200';

export function ean13CheckDigit(body12: string): number {
  const sum = [...body12].reduce((s, d, i) => s + Number(d) * (i % 2 === 0 ? 1 : 3), 0);
  return (10 - (sum % 10)) % 10;
}

export function isValidEan13(value: string): boolean {
  return /^\d{13}$/.test(value) && ean13CheckDigit(value.slice(0, 12)) === Number(value[12]);
}

/** Internal EAN-13 for a running number: "200" + 9 digits + check digit. */
export function internalBarcode(counter: number): string {
  const body = INTERNAL_PREFIX + String(counter).padStart(9, '0');
  return body + ean13CheckDigit(body);
}
